INSERT INTO `artikels` (`id`, `title`, `slug`, `content`, `excerpt`, `image`, `is_published`, `author_id`, `created_at`, `updated_at`) VALUES
(1, 'JAWAB PERMASALAHAN KEMISKINAN, BAZNAS DAN LAZISMU GELAR SOFT LAUNCHING PROGRAM KOLABORASI KEBAJIKAN ZAKAT', 'jawab-permasalahan-kemiskinan-baznas-dan-lazismu-gelar-soft-launching-program-kolaborasi-kebajikan-zakat', 'KABUPATEN SERANG -- Minimnya akses terhadap pendidikan, kesehatan, dan berbagai infrastruktur penunjang menjadi salah satu penyebab semakin lebarnya jarak kemiskinan. Melalui program Kolaborasi Kebajikan Zakat yang dijalin antara BAZNAS dan Lazismu, berbagai permasalahan kemiskinan diharapkan dapat teratasi dengan baik. Salah satu titik pelaksanaan program ini ada di Kampung Cerocoh, Desa Domas, Kecamatan Pontang, Kabupaten Serang, Banten.\r\nBertempat di Mushola Al-Maghfiroh Kampung Cerocoh, Lazismu dan BAZNAS mengadakan acara \"Soft Launching Program Kolaborasi Kebajikan Zakat\". Acara yang digelar pada Sabtu (23/04) ini dihadiri oleh Kepala Divisi Pendidikan dan Dakwah BAZNAS RI, Badan Pengurus Lazismu Pimpinan Pusat (PP) Muhammadiyah, Sekretaris Pimpinan Wilayah Muhammadiyah (PWM) Banten, Ketua Badan Pengurus Lazismu Wilayah Banten, Kepala Desa Domas, dan para undangan. Acara ini juga dimeriahkan dengan penyaluran alat baca dan tulis Al-Qur\'an, bantuan program Bakti Guru Lazismu, serta pengajian menjelang berbuka.\r\n\r\nFarid Septian, Kepala Divisi Pendidikan dan Dakwah BAZNAS RI dalam sambutannya menyampaikan, kolaborasi yang dijalin dengan ormas Islam seperti Muhammadiyah melalui Lazismu dilakukan karena BAZNAS memiliki keterbatasan. Menurutnya, dengan menjalin kolaborasi, tidak ada lagi yang menjadi pahlawan sendirian. Ormaslah yang paling memahami potensi lokal yang dimiliki masyarakat pada lokasi tertentu. Bantuan yang diberikan BAZNAS pun sifatnya merupakan stimulus, sehingga keberhasilan akan ditentukan oleh penerima manfaat, yaitu warga Desa Domas sendiri.\r\n\r\nIa pun berharap agar program ini dapat menjadi \"pilot project\" bagi daerah lain. \"Kami berharap ini menjadi titik pilot project yang bisa dibukukan dan diseminasikan menjadi contoh di tempat lain. Untuk Muhammadiyah dan Lazismu, Baznas bekerja sama di tiga titik, pertama di Banggai, di Banten, dan di Maluku. Programnya pendidikan, kesehatan, ekonomi, sosial dan sebagainya. Harapannya nanti ke depan ini sudah ada hasilnya,\" harapnya.\r\n\r\nMewakili Badan Pengurus Lazismu PP Muhammadiyah, Mohammad Danial Ramli juga menyebut bahwa program yang dijalin bersama BAZNAS sejalan dengan hasil Rapat Kerja Nasional (Rakernas) Lazismu yang dilaksanakan akhir tahun 2021 lalu, yaitu \"Inovasi Sosial\". \"Ini sesuai dengan harapan kami dari hasil Rakernas Lazismu yang mengusung tema Inovasi Sosial. Tentu saja inovasi-inovasi baru itu tidak bisa dilaksanakan sendiri, tetapi perlu ada kolaborasi. Kolaborasi ini bisa dilaksanakan dari berbagai pihak, bisa dari majelis, lembaga, dan ortom dari internal Muhammadiyah maupun dari instansi lain, yaitu kemitraan dengan BAZNAS. Alhamdulillah pada tahun ini kita mendapat kepercayaan,\" ungkapnya.\r\n\r\nSementara itu Ketua Lazismu Wilayah Banten, Mulyadi berharap agar dengan adanya program ini dapat membuat para warga yang sebelumnya merupakan penerima manfaat dapat menjadi pemberi manfaat. Ia pun juga menegaskan bahwa bantuan yang diberikan hanyalah bersifat stimulus. \"Targetnya adalah bagaimana para mustahik bisa menjadi muzakki. Awalnya diberi kemudian lama-lama bisa memberi. Bantuan ini hanya stimulus, artinya hanya sebagai rangsangan saja,\" tegasnya.\r\n\r\nTerakhir, Ukon Hidayat selaku Kepala Desa Domas juga menyambut baik dipilihnya Desa Domas sebagai titik pelaksanaan program. Pihaknya pun dapat turut menggunakan dana desa karena program ini sejalan dengan pembangunan yang digalakkan pemerintah. \"Kegiatan ini sangat baik sekali, semoga bisa selalu diridhoi Allah SWT. Tujuan dari program ini sangat baik sekali, karena bertujuan untuk meningkatkan kualitas kesehatan, pendidikan, dan ekonomi. Dana desa saat ini diperuntukan sebagaimana mestinya,\" pungkasnya.\r\n\r\nProgram Kolaborasi Kebajikan Zakat antara Baznas dan Lazismu ini adalah program yang dirancang untuk menjawab dan berbagai permasalahan di wilayah Indonesia dalam bingkai 3T (Terluar, Terdepan, Terdalam) khususnya untuk wilayah Maluku, Banggai, dan Serang, selain sebagai upaya membantu pemerintah dalam percepatan pengurangan kemiskinan yang terjadi di wilayah Indonesia. Program ini akan berfokus pada peningkatan layanan umum di bidang pendidikan, kesehatan, sosial, dakwah, dan kemanusiaan, dengan capaian akhir akan terbangun kekuatan dan kedaulatan ekonomi umat berbasis jamaah yang mampu menciptakan dukungan akses dan kualitas pada layanan umum tersebut.\r\n\r\n[PR Lazismu PP Muhammadiyah]', NULL, 'artikel/8CQJYgiJklBRXgYSzfj5AdzL0bdMts4YXEUGHWWP.jpg', 1, 1, '2025-11-20 11:05:18', '2025-12-19 03:12:32'),
(2, 'LAZISMU DAN BAZNAS MONEV PROGRAM KOLABORASI KEBAJIKAN ZAKAT DI SERANG', 'lazismu-dan-baznas-monev-program-kolaborasi-kebajikan-zakat-di-serang', 'KABUPATEN SERANG -- Jalinan kerja sama Lazismu dengan Badan Amil Zakat Nasional (BAZNAS) RI terus berlanjut. Kali ini, monitoring dan evaluasi (monev) dilakukan dalam Program Kolaborasi Kebajikan Zakat yang telah berjalan sejak bulan April hingga Desember 2022 lalu. Hal ini dalam rangka mengukur dan memastikan pelaksanaan kegiatan tetap pada jalurnya yaitu sesuai dengan pedoman dan perencanaan program. Selain itu juga agar dapat memberikan informasi kepada pengelola program apabila terjadi hambatan dan penyimpangan, serta sebagai masukan dalam melakukan evaluasi.\r\nKegiatan monev ini berlangsung di Desa Domas, Kecamatan Pontang, Kabupaten Serang, Banten sebagai titik pelaksanaan Program Kolaborasi Kebajikan Zakat BAZNAS-Lazismu. Selain monev, beragam agenda pun digelar mulai Rabu hingga Ahad (01-05/02), di antaranya adalah peresmian Pustu (Puskesmas Pembantu), layanan kesehatan, penyerahan alat bantu kesehatan, penyerahan bantuan beasiswa pendidikan, penyerahan Pemberian Makanan Tambahan (PMT), serta penyuluhan kesehatan dan kesehatan reproduksi/gizi. Acara ini dihadiri oleh perwakilan BAZNAS RI, Direktur Utama Lazismu Pimpinan Pusat (PP) Muhammadiyah, Kepala Desa Domas, Kepala Tata Usaha Puskesmas Pontang, Ketua BPD Desa Domas, Pimpinan Daerah Muhammadiyah (PDM) serta Pimpinan Daerah Aisyiyah (PDA) Kabupaten Serang, dan Lazismu Wilayah Banten.\r\n\r\nEdi Suryanto selaku Direktur Utama Lazismu PP Muhammadiyah menyambut baik program-program yang dijalankan dalam kolaborasi ini. Desa Domas di Banten merupakan titik ketiga dari Program Kolaborasi Kebajikan Zakat BAZNAS-Lazismu, selain di Banggai Sulawesi Tengah dan Maluku. Ia berharap agar program tersebut dapat terus berlanjut melalui Lazismu Wilayah Banten dan PDM serta PDA Kabupaten Serang.\r\n\r\n\"Harapan kami program ini bisa berkelanjutan dan berkesinambungan. Meskipun periode program sudah berhenti namun program ini tetap berjalan dengan dikawal khusus oleh Lazismu Wilayah Banten dan juga Pimpinan Daerah Muhammadiyah dan Pimpinan Daerah Aisyiyah Serang. InsyaAllah akan berlanjut terus menerus dan berkelanjutan,\" terang Edi.\r\n\r\n\r\nPenyerahan alat bantu kesehatan dari Direktur Utama Lazismu PP Muhammadiyah\r\nArdhi Lutfi Kautsar, Project Manager Program Kolaborasi Kebajikan Baznas-Lazismu 2022 yang juga merupakan Manajer Pendidikan, Dakwah, dan Sosial Lazismu PP Muhammadiyah menjelaskan, kerja sama yang dijalin bersama Baznas ini adalah dalam rangka meningkatkan mutu dan ekonomi masyarakat yang ada di tiga titik tersebut. Program-program yang dilaksanakan pun sejalan dengan Pilar Program yang ada di Lazismu, dengan harapan dapat meningkatkan kualitas mustahik menjadi muzakki. \"Harapannya masyarakat bisa lebih meningkatkan kualitasnya dari mustahik menjadi muzakki sebagai tujuan utama dalam program ini. Jauh dari itu, bisa menyejahterakan dengan mendayagunakan dana zakat yang berasal dari para agniya dan muzakki yang dititipkan pada Baznas kemudian disalurkan oleh Lazismu,\" ungkapnya.\r\n\r\nHarapan ini serupa dengan Staf Direktorat Pendistribusian BAZNAS RI, Ahmad Fadhil. Menurutnya, selain dapat memunculkan muzakki, program ini dapat menjadi pelajaran bersama dengan berbagi pengalaman selama pelaksanaan, terutama saat di lapangan. Ia juga berharap agar program ini dapat berjalan lancar hingga selesai dan mendapatkan hasil yang maksimal.\r\n\r\n\"Kami menyambut baik kerja sama ini dan sangat senang bisa berkolaborasi bersama, banyak praktik-praktik baik yang bisa kita bagi selama perjalanan program ini, baik itu praktik di Lazismu maupun di BAZNAS, termasuk dalam pelaksanaan program di lapangan. Kita sudah menyusun dari mulai perencanaan sampai monitoring dan nanti mudah-mudahan di akhir bisa mendapatkan hasil maksimal, bisa mendatangkan manfaat bagi mustahik. Mudah-mudahan kita bisa memunculkan muzakki di tengah-tengah program yang kita kolaborasikan bersama,\" sambut Fadhil.\r\n\r\n\r\nPara penerima manfaat beasiswa Program Kolaborasi Kebajikan Zakat BAZNAS-Lazismu\r\nMewakili para penerima manfaat, Ukon Hidayat selaku Kepala Desa Domas mengaku sangat bersyukur atas dipilihnya Desa Domas sebagai titik pelaksanaan Program Kolaborasi Kebajikan Baznas-Lazismu. Banyak manfaat yang bisa dirasakan oleh warganya, terutama dari sisi kesehatan. Dengan adanya program ini, layanan kesehatan untuk warga Desa Domas semakin meningkat.\r\n\r\n\"Sebelumnya pelayanan kesehatan ini hanya sebatas pengobatan biasa. Tapi ini rencana insyaAllah dari Lazismu dan Baznas akan ada peningkatan pelayanan, dari mulai penambahan tenaga perawat, apoteker, bahkan dokter. Semoga ke depan, pelayanan kesehatan di Desa Domas ini bisa meningkat sehingga masyarakat bisa mendapatkan pelayanan kesehatan yang cepat, tepat, dan aman,\" jelas Ukon.\r\n\r\n\r\nKegiatan penyuluhan kesehatan Program Kolaborasi Kebajikan Zakat BAZNAS-Lazismu\r\nBantuan untuk Pustu yang diberikan yaitu renovasi fisik dan layanan kesehatan kepada warga bekerja sama dengan Puskesmas Pontang. Lazismu juga melakukan aktivasi Pustu menjadi Pusat Layanan Kesehatan/Klinik Satelit di Desa Domas. Pada rangkaian kegiatan tersebut diserahkan alat bantu kesehatan berupa kursi roda dan alat bantu berjalan (tongkat). Di bidang pendidikan, 100 orang siswa penerima manfaat mendapatkan bantuan berupa paket \"School Kit\" dan bantuan pendidikan senilai masing-masing satu juta rupiah yang diserahkan dua kali dalam setahun. Di samping itu, anak-anak dan balita juga mendapatkan makanan tambahan berupa makanan pendukung gizi.\r\n\r\n[Kelembagaan dan Humas Lazismu PP Muhammadiyah]', NULL, 'artikel/tohd1GKG0DidgLZyA0V4i26r9yjiGbg9I4tjyYdT.jpg', 1, 1, '2025-11-20 11:05:54', '2025-12-19 03:11:23'),
(3, 'Lazismu Banten Salurkan Enam Ekor Sapi dari BPKH', 'lazismu-banten-salurkan-enam-ekor-sapi-dari-bpkh', 'SERANG - Banten menjadi salah satu provinsi yang menjadi tempat pelaksanaan kerja sama kurban antara Badan Pengelola Keuangan Haji (BPKH) RI dengan Lazismu. Selain Banten, ada 29 provinsi lain yang turut melaksanakan.\r\nLazismu Provinsi Banten bekerja sama dengan Badan Pengelola Keuangan Haji (BPKH) menyalurkan enam ekor sapi kurban kepada beberapa Pimpinan Daerah Muhammadiyah (PDM)/Lazismu Kabupaten/Kota dan Pimpinan Wilayah Muhammadiyah (PWM).\r\n\r\nKetua Lazismu Banten Dr. Muljadi mengatakan, penyebaran hewan-hewan kurban itu dimulai pada Rabu (21/7). Dibagikan ke Lebak, Pandeglang, dan beberapa yayasan lain.\r\n\r\n“Hari ini kami menyerahkan hewan kurban ke Pimpinan Daerah Muhammadiyah (PDM)/Lazismu Lebak 1 ekor sapi, Ikatan Alumni UIN Syarif Hidayatullah Tangsel 2 ekor sapi, Yayasan Al Firdaus 1 ekor sapi, dan PDM/Lazismu Pandeglang 1 ekor sapi,” ujarnya, Rabu (21/7/2021).\r\n\r\nSedangkan, satu ekor sapi yang lain akan diserahkan ke Pimpinan Wilayah Muhammadiyah (PWM) Banten.\r\n\r\n“Jadi total yang kami serahkan dari Lazismu Banten bekerjsama dengan BPKH RI sebanyak 6 sapi,” tegas dosen Universitas Muhammadiyah Tangerang ini.\r\n\r\nMuljadi berharap, penyerahan kurban ini dapat disembelih dengan tetap memberlakukan protokol kesehatan (prokes) yang ketat di masa PPKM Darurat ini.\r\n\r\nPemberian bantuan ini sesuai dengan komitmen BPKH dalam menyalurkan Nilai manfaat Dana Abadi Umat (DAU) melalui bidang kemaslahatan sebagaimana diatur dalam PP No 5 tahun 2018 Tentang pelaksanaan Undang-Undang No 34 tahun 2014 mengenai pengelolaan keuangan haji dan PBPKH No 7 Tentang prioritas kegiatan kemaslahatan.\r\n\r\nDistribusi Progam Kemaslahatan BPKH mencakup prasarana ibadah, kesehatan, pelayanan ibadah haji, ekonomi umat, pendidikan dan dakwah serta sosial keagamaan yang disalurkan secara langsung dan tidak langsung yang bermanfaat untuk kebaikan umat sesuai dengan asas prinsip syariah, kehati-hatian, manfaat, nirlaba, transparan dan akuntabel.\r\n\r\n(Yusuf)', NULL, 'artikel/3Q6fI32VgmmPI31MY5qVxcr9QhjRiggp0aYy7Zoh.jpg', 1, 1, '2025-11-20 11:06:42', '2025-12-19 03:10:22');

