--
-- Struktur dari tabel `campaigns`
--

CREATE TABLE `campaigns` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `program_id` bigint(20) UNSIGNED DEFAULT NULL,
  `title` varchar(255) NOT NULL,
  `description` text NOT NULL,
  `program_category` varchar(255) DEFAULT NULL,
  `target_amount` decimal(15,2) NOT NULL,
  `collected_amount` decimal(15,2) NOT NULL DEFAULT 0.00,
  `photo` varchar(255) DEFAULT NULL,
  `status` enum('draft','published','completed','cancelled') NOT NULL DEFAULT 'draft',
  `is_published` tinyint(1) NOT NULL DEFAULT 0,
  `created_by` bigint(20) UNSIGNED DEFAULT NULL,
  `end_date` date DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Dumping data untuk tabel `campaigns`
--

INSERT INTO `campaigns` (`id`, `program_id`, `title`, `description`, `program_category`, `target_amount`, `collected_amount`, `photo`, `status`, `is_published`, `created_by`, `end_date`, `created_at`, `updated_at`) VALUES
(1, 17, 'Beasiswa Mentari Pelajar Indonesia', 'Program beasiswa untuk pelajar dhuafa tingkat SD–SMA yang berprestasi namun memiliki keterbatasan ekonomi. Dana digunakan untuk seragam, buku, SPP, dan perlengkapan sekolah.', 'pendidikan', 150000000.00, 0.00, 'campaigns/R4T6bt0qsJFOR6suwWdJlzbWXIhB3kABF7VhgxV0.png', 'published', 1, 1, '2026-01-20', '2025-11-20 10:56:35', '2025-12-19 00:56:52'),
(2, 20, 'Sembako Keluarga Dhuafa', 'Pembagian paket sembako berisi beras, minyak, telur, dan kebutuhan pokok lainnya untuk keluarga miskin dan janda lansia.', 'sosial-dakwah', 50000000.00, 500000.00, 'campaigns/demo.png', 'completed', 1, 1, '2025-12-15', '2025-11-20 10:57:29', '2025-12-18 22:54:44'),
(3, 20, 'Program Bedah Rumah Layak Huni', 'Renovasi rumah tidak layak huni bagi keluarga dhuafa agar lebih aman, nyaman, dan sehat untuk ditempati.', 'sosial-dakwah', 250000000.00, 500000.00, 'campaigns/1v3EvU4pz5Se9H8BiQ2RBXOD9DkhfRVHxlrAfMx7.jpg', 'published', 1, 1, '2026-03-01', '2025-11-20 10:58:22', '2025-12-19 00:54:14'),
(4, 20, 'Dakwah Desa Binaan Mu’allaf', 'Program pembinaan rutin, pengadaan alat ibadah, dan pendampingan muallaf di desa binaan', 'sosial-dakwah', 60000000.00, 500000.00, 'campaigns/NM9WIyeBGBZcRKpAP7bVFULm64lmzWCE4tmrMjLJ.jpg', 'published', 1, 1, '2026-01-05', '2025-11-20 10:59:37', '2025-12-19 00:52:57'),
(6, NULL, 'Rumah hanyut, harta benda lenyap, dan masa depan tertunda oleh dahsyatnya Banjir Bandang dan Tanah Longsor yang melanda sepanjang Oktober hingga November 2025. Saatnya kita bertindak!', 'Panggilan Kemanusiaan Mendesak! Saat sebagian besar wilayah bersiap menyambut akhir tahun, puluhan ribu saudara kita di Aceh, Sumatera Utara (Sumut), dan Sumatera Barat (Sumbar) justru menghadapi kenyataan pahit akibat dampak masif Bencana Hidrometeorologi. Rumah hanyut, harta benda lenyap, dan masa depan tertunda oleh dahsyatnya Banjir Bandang dan Tanah Longsor yang melanda sepanjang Oktober hingga November 2025. Saatnya kita bertindak!\r\n\r\nSkala Krisis: Indonesia Siaga Bencana Akhir Tahun\r\nDalam kurun waktu dua bulan terakhir (Oktober–November 2025), Indonesia diguncang oleh serangkaian bencana hidrometeorologi parah. Data mencatat ribuan kejadian, di mana wilayah Sumatera menjadi titik fokus krisis.\r\n\r\nJenis Bencana: Banjir, Banjir Bandang, Tanah Longsor, dan Cuaca Ekstrem yang dipicu oleh tingginya curah hujan serta perkembangan seperti Siklon Tropis Senyar menjelang akhir November.\r\n\r\nWilayah Terdampak: Bencana ini melanda luas, dengan dampak terparah di Sumatera, termasuk banjir meluas di Aceh (misalnya di Kota Langsa dan Aceh Barat), longsor dan banjir di Sumatera Utara (melibatkan setidaknya 13 kabupaten/kota, termasuk Tapanuli Utara, Tapanuli Tengah, dan Padang Sidempuan), serta Banjir Bandang di Sumatera Barat (Kabupaten Agam dan Padang).\r\n\r\nDampak yang ditimbulkan sangat masif: korban jiwa, orang hilang, dan setidaknya puluhan ribu warga terpaksa mengungsi dan kehilangan tempat tinggal. Mereka kini kehilangan bukan hanya rumah, tetapi juga akses dasar krusial seperti pakaian, peralatan sanitasi dan kebersihan, hingga perlengkapan sekolah bagi anak-anak.\r\n\r\nWujudkan Kontribusi Terbaik Anda\r\nKita memiliki peran penting untuk meringankan beban mereka dan mempercepat pemulihan. Lazismu membuka peluang bagi Anda untuk terlibat dalam Aksi Nyata melalui program Bersama Bantu Aceh, Sumut, dan Sumbar Bangkit.\r\n\r\nDonasi Anda akan diwujudkan menjadi dua paket bantuan esensial:\r\n\r\nFamily Kit: Berisi kebutuhan pokok keluarga seperti sabun, sampo, selimut, dan perlengkapan khusus perempuan/anak.\r\n\r\nSchool Kit: Berisi tas, buku tulis, dan alat tulis, untuk memastikan keberlangsungan pendidikan anak-anak korban bencana.\r\n\r\nDengan donasi nominal Rp250.000,- per paket, Anda dapat secara langsung mengembalikan harapan satu keluarga atau mengamankan masa depan pendidikan satu anak.\r\n\r\nMari Kita Bantu Indonesia Pulih Segera!\r\nSetiap rupiah yang Anda sumbangkan adalah wujud nyata kepedulian dan Aksi Nyata yang sangat vital untuk proses pemulihan. Segera salurkan donasi terbaik Anda hari ini dengan menyertakan Kode Unik 013 pada transfer Anda (Contoh: Rp250.013,-).\r\n\r\nMari tunjukkan bahwa dalam kesulitan, kita adalah bangsa yang solid dan Bantu Indonesia Pulih Segera.', 'kemanusiaan', 300000000.00, 0.00, 'campaigns/U6SOdk33UFa8j1gY5TZmYyKLRuDBz4L5aJzPnT5e.png', 'published', 1, 1, '2026-01-19', '2025-12-19 02:06:21', '2025-12-19 02:06:21');

