INSERT INTO `news` (`id`, `title`, `content`, `image`, `slug`, `is_published`, `excerpt`, `author_id`, `created_at`, `updated_at`) VALUES
(1, 'Rakerwil LAZISMU Banten Diramaikan Seminar Bertema Akselerasi dan Transformasi LAZISMU Banten Unggul dan Maju', 'MELINTAS.ID- Pada Sabtu dan Ahad 23 -24 september 2023 Lembaga Amil Zakat Muhamadiyah (LAZISMU) Propinsi banten menggelar rapat Kerja Wilayah atau Rakerwil yang salah satu dari rangkaian acaranya seminar.\r\n\r\nBertempat di Gedung dakwah Muhamadiyah banten di Komp. Depag Cipocok  acara berjalan lancar dan meriah, tamu undangan tampak memenuhi aula, dan mobil memenuhi parkir Gedung.\r\n\r\nDengan tema seminar “Akselerasi dan Transformasi Menuju LAZISMU Banten Unggul dan Berkemajuan’ acara ini dihadiri pengurus LAZISMU Banten, Pengurus Wilayah Muhamadiyah Banten dan badan otonom tingkat daerah yang ada di Banten.\r\n\r\nSeminar yang ditujuakan agar memberikan pencerahan kepada para pengurus LAZISMU Banten, kali ini menghadirkan Narasumber yang mumpuni di Bidang Zakat Amil dan sedekah (ZIS) diantaranya :\r\n\r\nAbdul kahfi (Kepala Devisi penguatan pengumpulan ZIS Baznas RI),\r\nEdi Muktiono (Direktur Fundrising Lazismu PP Muhamadiyah),\r\nSamsul Hidayat ( Analisis Kebijakan Pemberdayaan Zakat Kanwil Kemenag Banten\r\nDr. H. Zakaria Syafei (Ketua Dewan Pengawas Lazismu Banten)\r\nPara narasumber dalam paparannya menyampaikan bahwa Lazismu harus berani berinovasi dengan habbit ummat Islam.\r\n\r\nDi era digital saat ini, kita bisa menggunakan berbagai Platform Media Digital, untuk mengajak umat berinfaq , bersedekah dan berzakat di Lazismu.\r\n\r\nKetua Lazismu Banten cahyo Hendro Atmoko menyampaikan bahwa tujuan acara rakerwil ini untuk penguatan organiasasi serta memperkaya literasi terkait Zakat infak dan sedekah.\r\n\r\nAdapun digelarnya acara rakerwil Lazismu yaitu untuk melakukan konsolidasi dan kordinasi antara perngurus Lazismu dan PW Muhamadiyah Banten supaya bisa lebih bersinergi.\r\n\r\nCahyo dalam kesempatan pres conference kepada Media menyampaikan harapannya agar ke depannya Laazismu semakin terdepan dalam optimalisasi peran LAZ di masyarakat Banten.\r\n\r\nAkan kami dorong penguatan kelembagaan Lazismu di Kabupaten dan Kota di Banten karena yang punya territorial dan kenggotaannya sesungguhnya PDM.\r\n\r\nDari rakerwil ini Cahyo optimis akan lahir program dan terobosan untuk meningkatkan kapasitas oragisasi juga perolehan ZIS dari anggota Muhamadiyah, pemerintah dan ummat serta perusahaan di Banten.\r\n\r\nDengan manajemen transparansi dan akuntabilitas dalam pelaporan dana masuk dan dana keluar, Cahyo Optimis, Lazismu Banten akan tumbuh dan berkembang menjadi ZIS yang ideal dan bermanfaat luas.', 'news/Qr7dA7MEtwPv0ZqTeTVQ3ohOVpiGtog9UMh52CEm.png', 'rakerwil-lazismu-banten-diramaikan-seminar-bertema-akselerasi-dan-transformasi-lazismu-banten-unggul-dan-maju', 1, NULL, 1, '2025-11-20 11:07:24', '2025-12-19 03:16:39'),
(2, 'Lazismu Bersama Alfamart dan Lembaga Lain Siapkan Ambulans Gratis untuk Warga Banten', 'TANGERANG - Jaringan minimarket Alfamart bekerja sama dengan Lembaga Zakat Infaq dan Shadaqah Muhammadiyah (Lazismu), Mizan Amanah, dan Yayasan Bahrul Maghfiroh Cinta Indonesia (BMCI) selaku pengelola donasi konsumen Alfamart menyiapkan mobil ambulans gratis yang bisa dimanfaatkan oleh warga Banten.\r\nLayanan ambulans dan tabung oksigen gratis merupakan hasil penggalangan donasi konsumen Alfamart dengan dukungan dari Sahabat Relawan Indonesia.\r\n\r\nAda enam mobil ambulans yang disiapkan untuk melayani masyarakat Banten, khususnya di wilayah Kota Tangerang, Kota Tangerang Selatan, Kota dan Kabupaten Serang, Kabupaten Lebak dan Kabupaten Pandeglang.\r\n\r\nTak cukup hanya dengan menyiapkan ambulans gratis, guna membantu penanganan Covid-19, Lazismu, Alfamart dan lembaga lain juga menyiapkan layanan pengisian tabung oksigen dan peminjaman tabung oksigen gratis bagi warga Serang dan sekitarnya.\r\n\r\n“Kami siapkan layanan ambulans gratis ini tujuannya agar layanan ambulans bagi masyarakat tidak terkendala. Masyarakat Banten dapat mengakses nomor WhatsApp 082166166911 atau 081350004544, dan khususnya bagi warga Serang dan sekitarnya kami telah siapkan layanan peminjaman tabung oksigen gratis,” kata Koordinator Sahabat Relawan Indonesia, Arif Kirdiat dalam keterangan tertulis, Minggu (3/10/2021).\r\n\r\nManager Pendayagunaan dan Distribusi Lazismu Falhan Nian Akbar menyampaikan, penyediaan layanan ambulans dan tabung oksigen merupakan aksi kemanusiaan untuk membantu masyarakat yang terdampak Covid-19.\r\n\r\n“Dengan kegiatan seperti ini kita bisa membantu masyarakat yang membutuhkan layanan ambulans, peminjaman dan pengisian tabung oksigen gratis di wilayah Banten,” katanya.\r\n\r\nSebagaimana diketahui, Lazismu menjalin kerja sama dengan Alfamart dalam menyalurkan donasi kembalian konsumen. Pada tahun 2021, kerja sama tersebut digelar pada bulan September hingga Desember 2021. Sementara itu, mobil ambulans tersebut berasal dari hasil donasi tahun lalu.\r\n\r\n(Nda/Yusuf)', 'news/YCrPTdNDJS9uF3IACNVm2yA03D8JMermwtiQTj7j.jpg', 'lazismu-bersama-alfamart-dan-lembaga-lain-siapkan-ambulans-gratis-untuk-warga-banten-1', 1, 'TANGERANG - Jaringan minimarket Alfamart bekerja sama dengan Lembaga Zakat Infaq dan Shadaqah Muhammadiyah (Lazismu), Mizan Amanah, dan Yayasan Bahrul...', 1, '2025-11-20 11:07:55', '2025-12-19 03:17:34');

