--
-- Trigger `zakat_payments`
--
DELIMITER $$
CREATE TRIGGER `chk_received_by_role_insert` BEFORE INSERT ON `zakat_payments` FOR EACH ROW BEGIN
                IF NEW.received_by IS NOT NULL THEN
                    IF NOT EXISTS (
                        SELECT 1 FROM users 
                        WHERE users.id = NEW.received_by 
                        AND users.role = 'admin'
                    ) THEN
                        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'received_by must reference a user with admin role';
                    END IF;
                END IF;
            END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `chk_received_by_role_update` BEFORE UPDATE ON `zakat_payments` FOR EACH ROW BEGIN
                IF NEW.received_by IS NOT NULL THEN
                    IF NOT EXISTS (
                        SELECT 1 FROM users 
                        WHERE users.id = NEW.received_by 
                        AND users.role = 'admin'
                    ) THEN
                        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'received_by must reference a user with admin role';
                    END IF;
                END IF;
            END
$$
DELIMITER ;

